// PreToolUse hook — block writes to build output and secrets.
//
// dist/ and yena-clipper.zip are regenerated by `npm run build`; editing them is
// always a mistake (the change is silently lost on the next build). .env holds real
// tokens. Exit 2 = deny the tool call and show stderr to Claude.

import { relative, isAbsolute } from 'node:path';

const input = await new Promise((resolve) => {
  let raw = '';
  process.stdin.on('data', (c) => (raw += c));
  process.stdin.on('end', () => resolve(raw));
});

let payload;
try { payload = JSON.parse(input || '{}'); } catch { process.exit(0); }

const file = payload?.tool_input?.file_path;
if (!file) process.exit(0);

const root = payload.cwd || process.cwd();
const rel = isAbsolute(file) ? relative(root, file) : file;

const RULES = [
  [/^dist\//, 'dist/ is build output — edit the matching file in src/ and run `npm run build`.'],
  [/\.zip$/, 'The zip is produced by `npm run build` — never hand-edit it.'],
  [/(^|\/)\.env$/, '.env holds real secrets. Edit .env.example instead, and ask the user to fill in .env themselves.'],
];

for (const [pattern, reason] of RULES) {
  if (pattern.test(rel)) {
    console.error(`Blocked write to ${rel}: ${reason}`);
    process.exit(2);
  }
}
